#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n,m;
    cin>>n>>m;
    int a[10];
    for(int i=0;i<10;i++) cin>>a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    vector<unordered_set<int>> adjset(n+1);
    for(int i=0;i<m;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        radj[v].push_back(u);
        adjset[u].insert(v);
    }

    auto now=chrono::steady_clock::now;
    auto start_time=now();
    auto elapsed_ms=[&](){return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count();};

    // Check DAG - longest path
    {
        vector<int> indeg(n+1,0);
        for(int u=1;u<=n;u++) for(int v:adj[u]) indeg[v]++;
        queue<int> q;
        for(int u=1;u<=n;u++) if(indeg[u]==0) q.push(u);
        vector<int> topo;
        topo.reserve(n);
        while(!q.empty()){int u=q.front();q.pop();topo.push_back(u);for(int v:adj[u])if(--indeg[v]==0)q.push(v);}
        if((int)topo.size()==n){
            vector<int> dp(n+1,1),nxt(n+1,-1);
            for(int i=n-1;i>=0;i--){
                int u=topo[i]; dp[u]=1; nxt[u]=-1;
                for(int v:adj[u]) if(dp[v]+1>dp[u]){dp[u]=dp[v]+1;nxt[u]=v;}
            }
            int bs=topo[0]; for(int u:topo) if(dp[u]>dp[bs]) bs=u;
            vector<int> path; for(int u=bs;u!=-1;u=nxt[u]) path.push_back(u);
            cout<<path.size()<<"\n";
            for(int i=0;i<(int)path.size();i++){if(i)cout<<' ';cout<<path[i];}
            cout<<"\n";
            return 0;
        }
    }

    mt19937 rng(42);
    vector<int> best_path;

    auto has_edge=[&](int u,int v)->bool{return adjset[u].count(v);};

    auto try_improve=[&](vector<int>& path){
        vector<bool> inpath(n+1,false);
        for(int v:path) inpath[v]=true;
        // Try to extend back
        for(;;){int c=path.back();vector<int> cands;for(int v:adj[c])if(!inpath[v])cands.push_back(v);if(cands.empty())break;int pick=cands[rng()%cands.size()];path.push_back(pick);inpath[pick]=true;}
        // Try rotation extension
        for(int iter=0;iter<(int)path.size()*2&&(int)path.size()<n;iter++){
            int last=path.back();
            vector<int> cands;
            for(int i=1;i<(int)path.size()-1;i++) if(has_edge(last,path[i])) cands.push_back(i);
            if(cands.empty()) break;
            int idx=cands[rng()%cands.size()];
            reverse(path.begin()+idx,path.end());
            // extend
            for(;;){int c=path.back();vector<int> nb;for(int v:adj[c])if(!inpath[v])nb.push_back(v);if(nb.empty())break;int p=nb[rng()%nb.size()];path.push_back(p);inpath[p]=true;}
        }
        if((int)path.size()>(int)best_path.size()) best_path=path;
    };

    while(elapsed_ms()<4700&&(int)best_path.size()<n){
        int sv=rng()%n+1;
        vector<int> path={sv};
        vector<bool> inpath(n+1,false); inpath[sv]=true;
        for(;;){int c=path.back();vector<pair<int,int>>nb;for(int v:adj[c])if(!inpath[v]){int s=0;for(int w:adj[v])if(!inpath[w])s++;nb.push_back({s,v});}if(nb.empty())break;sort(nb.begin(),nb.end());int pick=nb[0].second;if(nb.size()>1&&rng()%4==0)pick=nb[rng()%min((int)nb.size(),3)].second;path.push_back(pick);inpath[pick]=true;}
        try_improve(path);
    }

    cout<<best_path.size()<<"\n";
    for(int i=0;i<(int)best_path.size();i++){if(i)cout<<' ';cout<<best_path[i];}
    cout<<"\n";
}
